'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Reward, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './reward.css'

import { LockGlyph } from './glyphs'

/**
 * Reward: one thing a player can be given.
 *
 * A prize, a badge, a pack, a ticket, a discount code. It renders the object
 * and where that object is in its lifecycle, and it does nothing else. It does
 * not decide that a reward was earned, does not fetch it, does not claim it and
 * does not know what it is worth. Rewards are settled by the host (BDS-023 and
 * the attribute contract's "`rewarded` is a state without an event"), so every
 * lifecycle change arrives as a prop.
 *
 * The lifecycle lives on `data-gs-reward-state` and deliberately not on
 * `data-gs-state`. `data-gs-state` is the settled outcome of something the
 * player did: set once, never revisited, and the three-things rule is defined
 * against exactly its three values. This one is host-driven and revisited over
 * time. Two concerns, two attributes. A locked reward is
 * `data-gs-reward-state="locked"` and never `data-gs-locked`, which stays a
 * control attribute.
 *
 * Revealing is the one thing a player does here, so a revealable reward is a
 * real `<button>` and Enter and Space work without any key handling of our own.
 */

export type RewardState = 'locked' | 'available' | 'earned' | 'claimed'

export interface RewardProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children'> {
  /** The reward's id. Machine-readable, and what an inventory keys on. */
  id: string
  /** Where the reward is in its lifecycle. Host-driven, always. */
  state: RewardState
  /** The reward's name, as a player reads it. */
  label: string
  /** A supporting line. Never carries meaning the label does not. */
  detail?: string
  /**
   * What the reward is worth, as a number: 500 coins, 3 packs. Rendered beside
   * the name and carried machine-readably on `data-gs-value`.
   */
  value?: number
  /** The reveal has played. Only meaningful while the reward is earned. */
  revealed?: boolean
  /**
   * The player opening the reward. Supplying it makes the reward a real button,
   * focusable and operable from the keyboard. It fires only while the reward is
   * earned and unrevealed; at every other point in the lifecycle there is
   * nothing to open.
   */
  onReveal?: (id: string) => void
}

/**
 * Glyphs, because a lifecycle that is only a colour is not a lifecycle. Four
 * distinguishable shapes, readable with no colour and no motion at all.
 *
 * `locked` is drawn rather than typed. It was a colour emoji padlock, which
 * ignored every colour token and changed silhouette per operating system
 * (GSUI-103); the other three are text-presentation characters that already
 * take `currentColor`, so they stayed as they are. The emoji character is not
 * repeated in this comment: the gate greps the source for emoji, and a mention
 * would read as a use.
 */
const GLYPH: Record<RewardState, React.ReactNode> = {
  locked: <LockGlyph />,
  available: '☆',
  earned: '★',
  claimed: '✓',
}

/**
 * The waiting glyph. BDS-023 loops `motion.pulse` on an unrevealed reward, and
 * that is a `motion` element, so under reduced motion it stops dead. The
 * waiting state therefore also exists as this glyph and as the reward colour
 * behind it, and `reward.test.tsx` asserts exactly that.
 */
const WAITING_GLYPH = '?'

/**
 * The words that go with the states, fixed by the attribute contract's
 * accessible-name table so that reward, inventory and everything downstream
 * cannot ship three vocabularies for one lifecycle.
 */
const STATE_LABEL: Record<RewardState, string> = {
  locked: 'locked',
  available: 'available',
  earned: 'earned',
  claimed: 'claimed',
}

const WAITING_LABEL = 'waiting'

/** The accessible name, in one place, because the inventory reads it too. */
export function rewardName({
  label,
  state,
  value,
  revealed,
}: Pick<RewardProps, 'label' | 'state' | 'value' | 'revealed'>): string {
  // What it is, then what it is worth, then what is true about it. The same
  // order `stat` uses, for the same reason: a screen reader user gets no fill,
  // no glyph and no motion, so the name has to carry all of it.
  const words: string[] = [label]
  if (value !== undefined) words.push(String(value))
  words.push(STATE_LABEL[state])
  if (state === 'earned' && !revealed) words.push(WAITING_LABEL)
  return words.join(', ')
}

export function Reward({
  id,
  state,
  label,
  detail,
  value,
  revealed = false,
  onReveal,
  className,
  onClick,
  ...rest
}: RewardProps) {
  // Earned and not yet opened. The only point in the lifecycle where a press
  // means anything.
  const waiting = state === 'earned' && !revealed
  // Supplying `onReveal` decides the element type, not `waiting` does. If the
  // root switched from <button> to <div> on reveal, the press that revealed it
  // would destroy the focused element and drop focus to the body, which is the
  // exact moment a keyboard player most needs to stay where they are.
  const interactive = onReveal !== undefined

  const attributes = {
    ...rest,
    // No gs-action-type here, deliberately. The root is a button, and its
    // content is an object's name, its value and a line of detail rather than
    // the word on a control you press to commit. Typing the whole subtree made
    // arcade shout the reward's name and its detail line at weight 900. A
    // reward has no action text of its own, so it carries none of that axis;
    // gs-reward__value carries gs-display-type, which is the axis a number
    // wants.
    className: ['gs-reward', className].filter(Boolean).join(' '),
    'data-gs-component': 'reward',
    'data-gs-reward': id,
    'data-gs-reward-state': state,
    // Boolean attributes are `true` or absent, never `"false"`: a selector for
    // the absence of `false` matches an element that does not exist.
    'data-gs-revealed': revealed ? 'true' : undefined,
    'data-gs-value': value,
    'aria-label': rewardName({ label, state, value, revealed }),
  }

  // Everything inside is hidden: the root's label above is the accessible name,
  // and announcing the pieces again would read the reward twice.
  const inner = (
    <>
      {/* The offset base the face collapses onto, the reserved part names, so a
          theme and a test find it the way they find a button's. */}
      <span className="gs-reward__base" data-gs-scope="reward" data-gs-part="base" aria-hidden="true" />
      <span
        className="gs-reward__face"
        data-gs-scope="reward" data-gs-part="face"
        data-gs-animates="motion"
        aria-hidden="true"
      >
        {/* Emphasis, never motion: this is the change that survives reduced
            motion, and it is how the waiting state stays visible once the pulse
            has stopped. */}
        <span className="gs-reward__glyph" data-gs-scope="reward" data-gs-part="glyph" data-gs-animates="emphasis">
          {waiting ? WAITING_GLYPH : GLYPH[state]}
        </span>
        <span className="gs-reward__label" data-gs-scope="reward" data-gs-part="label">
          {label}
        </span>
        {value !== undefined ? (
          <span className="gs-reward__value gs-display-type" data-gs-scope="reward" data-gs-part="value">
            {value}
          </span>
        ) : null}
        {detail ? (
          <span className="gs-reward__detail" data-gs-scope="reward" data-gs-part="detail">
            {detail}
          </span>
        ) : null}
      </span>
      {waiting ? (
        // The pulse, and only the pulse, is motion. It stops entirely under
        // reduced motion, which is why the glyph above exists.
        <span
          className="gs-reward__pulse"
          data-gs-scope="reward" data-gs-part="pulse"
          data-gs-animates="motion"
          aria-hidden="true"
        />
      ) : null}
    </>
  )

  if (!interactive) {
    return (
      <div {...attributes} role="group" onClick={onClick as React.MouseEventHandler<HTMLDivElement>}>
        {inner}
      </div>
    )
  }

  return (
    <button
      {...attributes}
      type="button"
      // Honest about what the press does. A claimed reward rendered inside an
      // inventory that passes one `onReveal` for the whole collection is still
      // a button, and telling a screen reader it can be pressed would be a lie.
      // aria-disabled rather than the native attribute: the reward stays
      // reachable, so it can still be read.
      aria-disabled={waiting ? undefined : true}
      onClick={(event) => {
        if (!waiting) {
          // A host may have overridden `type`, and a reward that is not waiting
          // must not submit a form.
          event.preventDefault()
          return
        }
        ;(onClick as React.MouseEventHandler<HTMLButtonElement> | undefined)?.(event)
        onReveal?.(id)
      }}
    >
      {inner}
    </button>
  )
}

/* Reward. Every value comes from a token; nothing here is a literal colour. */

.gs-reward {
  position: relative;
  display: inline-grid;
  place-items: center;
  min-height: var(--gs-size-action-large);
  min-width: var(--gs-size-touch-min);
  padding: 0;
  border: 0;
  background: none;
  text-align: center;
  /* A reward is an object, so it reads at the object icon size rather than the
     control size. */
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  color: var(--gs-color-ink);
}

/* Only a reward that can be opened invites a press. */
.gs-reward[data-gs-reward-state='earned']:not([data-gs-revealed]) { cursor: pointer; }
.gs-reward[aria-disabled='true'] { cursor: default; }

.gs-reward:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

/* -- the object ----------------------------------------------------------- */
/* Base and face, as on a pressable control: the base collapses and the face
   travels the same distance, so the face lands where the base was. A reward
   that fades on press would read as disabled. */
.gs-reward__base {
  grid-area: 1 / 1;
  align-self: stretch;
  justify-self: stretch;
  border-radius: var(--gs-radius-lg);
  background: var(--gs-color-reward-base);
}

.gs-reward__face {
  grid-area: 1 / 1;
  align-self: stretch;
  justify-self: stretch;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-1);
  padding: var(--gs-space-3) var(--gs-space-4);
  border-radius: var(--gs-radius-lg);
  background: var(--gs-color-surface-raised);
  box-shadow: var(--gs-depth-raised);
  /* The reveal, BDS-023: 600ms of motion.reveal. Motion only, so it goes to
     zero under reduced motion and the reward simply is revealed. */
  transition: transform var(--gs-motion-reveal) ease-out,
              box-shadow var(--gs-motion-reveal) ease-out;
}

/* The depth change matters as much as the movement. This face has no offset
   base to collapse, so when the press gesture is `none` - which is what a theme
   may choose, and what the build forces under reduced motion - the transform
   alone would leave the press with no response at all. Dropping to depth.flat
   is that response, and it is a depth change rather than a movement, so it
   survives. */
.gs-reward[data-gs-reward-state='earned']:not([data-gs-revealed]):active .gs-reward__face {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-flat);
}

.gs-reward__glyph {
  font-size: var(--gs-size-icon-object);
  line-height: 1;
  color: var(--gs-color-ink-secondary);
  /* Emphasis, not motion: this duration survives reduced motion on purpose. It
     is how a player who sees no movement still sees the state change. */
  transition: color var(--gs-motion-emphasis) ease-out,
              opacity var(--gs-motion-emphasis) ease-out;
}

.gs-reward__label {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  text-transform: uppercase;
}

.gs-reward__value {
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
}

.gs-reward__detail {
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-label-font-size);
  color: var(--gs-color-ink-secondary);
}

/* -- the lifecycle -------------------------------------------------------- */
/* Each state changes the surface, the glyph and the text at once. A state that
   is only a colour fails the accessibility stage, and rightly. */

/* Locked: it exists and it is not yours yet. Flat, dimmed, padlock. */
.gs-reward[data-gs-reward-state='locked'] .gs-reward__face {
  background: var(--gs-color-disabled);
  box-shadow: var(--gs-depth-flat);
  color: var(--gs-color-disabled-ink);
}

.gs-reward[data-gs-reward-state='locked'] .gs-reward__glyph {
  color: var(--gs-color-disabled-ink);
}

/* Available: reachable, not yet taken. It has its shape back and an edge. */
.gs-reward[data-gs-reward-state='available'] .gs-reward__face {
  border: var(--gs-stroke-ui) solid var(--gs-color-edge-high);
  box-shadow: var(--gs-depth-raised);
}

.gs-reward[data-gs-reward-state='available'] .gs-reward__glyph {
  color: var(--gs-color-reward);
}

/* Earned: the ring and glow from the three-things table, and the reward mark. */
.gs-reward[data-gs-reward-state='earned'] .gs-reward__face {
  box-shadow: var(--gs-depth-reward);
}

.gs-reward[data-gs-reward-state='earned'] .gs-reward__glyph {
  color: var(--gs-color-reward);
}

/* Claimed: it happened, it is done, it stops shouting. Tick, no glow. */
.gs-reward[data-gs-reward-state='claimed'] .gs-reward__face {
  background: var(--gs-color-surface);
  box-shadow: var(--gs-depth-flat);
}

.gs-reward[data-gs-reward-state='claimed'] .gs-reward__glyph {
  color: var(--gs-color-positive);
}

/* -- waiting to be opened ------------------------------------------------- */
/* The pulse is the only motion here and it stops dead under reduced motion, so
   waiting is carried by the glyph and the fill as well. Both of those are
   emphasis and both survive. This is the rule BDS-023 exists to state. */
.gs-reward[data-gs-reward-state='earned']:not([data-gs-revealed]) .gs-reward__face {
  background: var(--gs-color-reward-base);
  color: var(--gs-color-on-bright);
}

.gs-reward[data-gs-reward-state='earned']:not([data-gs-revealed]) .gs-reward__glyph {
  color: var(--gs-color-on-bright);
}

.gs-reward__pulse {
  grid-area: 1 / 1;
  align-self: stretch;
  justify-self: stretch;
  border-radius: var(--gs-radius-lg);
  box-shadow: var(--gs-depth-reward);
  pointer-events: none;
  animation: gs-reward-pulse var(--gs-motion-pulse) ease-in-out infinite;
}

/* A zero-duration animation still runs, once, at frame nought. The token goes
   to 0ms under reduced motion, so this resolves to nothing moving. */
@keyframes gs-reward-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.55; transform: scale(1.03); }
}
